from pathlib import Path
import re, shutil
R=Path(__file__).resolve().parents[1];O=R/'outputs';W=R/'work'
for name in ['report.html','gallery.html','literature.html']:
    p=W/('before_explained_'+name)
    if not p.exists():shutil.copy2(O/name,p)
s=(W/'before_explained_report.html').read_text(encoding='utf-8')
def section(name):return re.search(r'<section id="'+name+r'">(.*?)</section>',s,re.S).group(1)
def replace(name,body):
    global s
    s=re.sub(r'<section id="'+name+r'">.*?</section>',lambda m:'<section id="'+name+'">'+body+'</section>',s,flags=re.S)
def ul(items):return '<ul class="facts">'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def p(t):return '<p class="explain">'+t+'</p>'
def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def tables(t):return re.findall(r'<div class="table-wrap[^\"]*">.*?</div>',t,re.S)

intro='<section id="overview"><h2>이번에 한 일부터 간단히 설명하면</h2>'+p('대회 이미지에는 사진만 있는 것도 있고, 한글 안내문이나 로고처럼 <b>글자를 읽어야 내용을 알 수 있는 이미지</b>도 있었다. 그래서 이미지를 설명하는 모델 하나만으로 필요한 정보를 다 얻을 수 있는지부터 확인하고자 하였다.')+p('이를 위해 관련 논문을 찾아보고, 공개된 모델 중 <b>그림을 설명하는 모델 2개와 글자를 읽는 OCR 도구 2개</b>를 골라 로컬 샘플에 실행하였다. 작은 글자는 확대하고, 긴 포스터는 나눠 읽어 보는 처리도 추가하였다.')+p('돌려 보니 글자는 OCR에서 더 직접적으로 얻을 수 있었고, 그림 설명 모델은 장면을 알려주면서도 없는 내용을 덧붙이는 경우가 있었다. <b>현재까지 만든 것은 이미지에서 정보를 뽑아 비교·저장하는 실험 도구이다.</b> 이 결과를 Gemma에 넣어 최종 판정하는 단계는 아직 진행하지 않았다.')+'</section>'
s=s.replace('<section id="contents">',intro+'<section id="contents">',1)
contents='<h2>이 자료는 아래 순서로 읽으면 된다</h2>'+table(['순서','팀원이 이해하면 되는 내용','이동'],[
['1','왜 이미지 설명만으로 충분한지 의심했는가','<a href="#problem">출발점</a>'],['2','어떤 논문을 찾았고, 왜 이 네 모델을 골랐는가','<a href="#research">자료 조사와 모델 선택</a>'],['3','대회 샘플은 어떤 상태였고, 어떻게 준비했는가','<a href="#data">샘플 준비</a>'],['4','공개 모델을 활용해 실제로 무엇을 만들어 돌렸는가','<a href="#runs">구현한 실험 도구</a>'],['5','돌려 보니 무엇이 되고, 무엇이 안 되었는가','<a href="#findings">결과 해석</a>'],['6','실제 이미지와 출력을 나란히 보면 어떤 차이인가','<a href="#examples">대표 사례 12개</a>'],['7','이 결과를 다음 LLM 단계에 어떻게 연결할 것인가','<a href="#next">다음 구성</a>']])
replace('contents',contents)
replace('problem','<h2>1. 시작은 “사진 설명 모델로 한글 안내문도 설명할 수 있을까?”였다</h2>'+p('기존에 검토하던 Patch-ioner는 이미지의 전체 또는 일부 영역을 문장으로 설명하는 방법이다. 그런데 우리 샘플에는 기관 로고, 날짜가 적힌 행사 포스터, 숫자와 창구명이 들어간 배치도도 있었다. 이런 이미지에서는 “사람이 있다”, “표지판처럼 보인다”는 설명만 얻어서는 중요한 정보가 빠진다.')+p('예를 들어 국민연금 홍보 이미지에서 가족 사진을 잘 설명하더라도, <b>“국민연금”이라는 글자를 놓치면 무슨 안내인지 알기 어렵다.</b> 반대로 글자만 읽으면 사진 속 대상이나 도형의 의미가 빠질 수 있다. 따라서 다음 두 작업을 나누어 조사하였다.')+ul(['<b>그림·사진 설명:</b> 무엇이 있고, 어떤 장면이며, 대상이 어떻게 배치되어 있는지 추출한다. 이를 이미지 캡셔닝이라고 한다.','<b>글자 읽기:</b> 이미지 속 글자의 위치를 찾고, 실제 문자열로 바꾼다. 이 작업이 OCR이다. 글자 위치만 찾는 text detection과 구분하였다.'])+p('우리의 최종 목적은 기존 alt가 적절한지 판단할 근거를 마련하는 것이다. 이번에는 그 앞단인 <b>이미지 정보 추출 방법</b>을 시험하였다. 최종 대회 과제와 분류 형식은 <a href="https://aida.kisti.re.kr/competition/main/problem/PROB_000000000004610/detail.do">공식 문제 설명</a>에서 확인하였다.'))

research_old=section('research'); candidate_table=tables(research_old)[0]
research='<h2>2. 논문을 조사한 뒤, 비교할 모델 네 개를 골랐다</h2><h3>2-1. 논문 이름보다 “우리 이미지에 실제로 쓸 수 있는가”를 확인하였다</h3>'+p('조사는 그림 설명, OCR·문서 읽기, 설명 오류를 줄이는 방법으로 나누어 진행하였다. 2026년 후보 20개를 비교하면서 논문의 방법을 읽고, 공식 GitHub와 모델 배포 페이지를 찾아 실제 실행 가능한 상태인지 확인하였다.')+ul(['<b>논문에서 확인한 것:</b> 이미지 한 장을 넣으면 무엇이 나오는지, 어떤 비전 처리를 추가하는지 확인하였다.','<b>코드에서 확인한 것:</b> 저장소에 소개글만 있는지, 실행 코드와 모델 파일까지 있는지 확인하였다.','<b>한국어에서 확인한 것:</b> 한국어로 답할 수 있다는 설명과, 이미지 속 한글을 읽는 근거를 구분하였다.','<b>학습 조건:</b> 이번에는 이미 공개된 모델을 사용하고, 대회 데이터로 추가 학습하지 않는 방식으로 한정하였다.'])+p('조사해 보니, 아이디어는 적합해도 실행 코드가 없는 방법이 있었고, 글자는 읽지만 사진의 의미까지 설명하지는 않는 방법도 있었다. 지정한 모든 조건을 동시에 확인한 완성형 방법은 이번 후보군에서 찾지 못하였다. 그래서 <b>역할을 나누어 실제로 돌려 볼 수 있는 구성</b>을 먼저 만들었다.')
research+='<h3>2-2. 네 모델은 각각 이런 일을 맡았다</h3>'+table(['모델','쉽게 말하면','이번에 넣은 이유'],[
['<b>Patch-ioner</b>','이미지 전체나 선택한 부분을 한 문장으로 설명하는 모델이다.','기존에 검토한 방법이므로, 우리 이미지에서도 설명이 잘 나오는지 확인하였다.'],
['<b>Florence-2-base</b>','Microsoft의 이미지 이해 모델이다. 그림·사진을 자세히 설명하고 영역별 설명도 뽑을 수 있다.','Patch-ioner와 다른 설명 모델을 함께 써서 장면·도형 설명이 달라지는지 비교하였다.'],
['<b>PP-OCRv5 한국어</b>','이미지에 실제로 쓰인 한글을 문자열로 읽는 OCR 모델이다.','기관명·날짜·전화번호처럼 caption만으로 놓칠 수 있는 정보를 읽게 하였다.'],
['<b>EasyOCR</b>','한국어·영어를 읽을 수 있는 별도의 OCR 도구이다.','한 OCR의 출력을 그대로 믿지 않고, 다른 도구와 읽은 결과를 비교하였다.']])
research+=p('<b>Florence와 EasyOCR는 2026년 논문 조건을 충족한 최종 선정작이라는 뜻으로 넣지 않았다.</b> 실제 비교 실험을 위한 기존 도구로 사용하였다. 논문 선별 기준과, 실험에 쓸 비교 도구의 선택을 분리한 것이다.')+p('학회 기준도 따로 대조하였다. 사용자가 지정한 BK21 표에서는 CVPR의 발표 유형별 값이 달랐으므로, CVPR이라는 이름만으로 기준을 통과시킨 것은 아니다. 후보별 근거는 아래 표와 별도 조사 노트에 남겼다.')+'<details><summary>논문·공식 코드 링크와 선별 근거 표 보기</summary>'+candidate_table+'</details><p class="jump"><a href="literature.html">20개 후보의 조사 내용과 논문·GitHub 링크 →</a></p>'
replace('research',research)

d=section('data')
d=d.replace('<h2>3. 샘플 데이터는 어떻게 처리하였는가</h2>','<h2>3. 샘플을 열어 보니, 같은 방식으로 넣기 어려운 이미지가 섞여 있었다</h2>'+p('실험에는 로컬에 저장된 대회 샘플 299개를 사용하였다. 큰 사진부터 16×16 숫자, 배경이 투명한 아이콘, 글자가 많은 포스터까지 크기와 형태가 달랐다. 먼저 파일을 제대로 열 수 있는지 확인한 뒤 모델에 넣는 과정을 만들었다.'))
d=d.replace('<h3>3-2. 원본을 보존하고, 입력 표현을 정리하였다</h3>','<h3>3-2. 모델이 이미지를 제대로 볼 수 있도록 준비하였다</h3>'+p('여기서 전처리는 새로운 정보를 만들어 내는 일이 아니다. 이미지의 방향을 맞추고, 투명한 부분에 배경을 넣고, 지원하지 않는 파일을 읽을 수 있게 변환하는 준비 작업이다. 어떤 처리를 했는지 추적할 수 있도록 원본 파일과 결과를 구분해 저장하였다.'))
d=d.replace('<h3>3-3. 전처리는 이런 차이를 만들었다</h3>','<h3>3-3. 잘 안 읽히는 입력에는 세 가지 보완을 시험하였다</h3>'+p('글자를 못 읽었다고 모두 같은 원인은 아니었다. 너무 작은 글자는 확대하고, 밝은 투명 글자는 배경을 어둡게 바꾸고, 큰 포스터는 작은 구역으로 나눠 읽어 보았다. 아래 예시는 실제 실험에서 확인한 차이다.'))
d=d.replace('<h3>3-4. 전체 299개와 자세히 볼 42개를 나누었다</h3>','<h3>3-4. 전체 실행과 자세한 내용 검토를 나누었다</h3>'+p('모델이 결과를 반환하는지는 전체 299개에서 확인하였다. 다만 결과가 실제 이미지와 맞는지 자세히 비교하려면 유형별 검토가 필요했다. 그래서 사진·아이콘·로고 등 36개에 작거나 큰 이미지 6개를 더해 42개를 따로 살펴보았다. 42개는 새 데이터가 아니라 299개 중에서 고른 일부이다.'))
d=d.replace('파일 내용의 고유 SHA-256은 289개였다. 동일한 파일 내용이 중복되어 있었다.','파일 내용을 구분하는 값인 SHA-256으로 비교하니, 서로 다른 이미지 내용은 289개였다. 299개 파일 안에 같은 내용의 중복이 있었다.')
replace('data',d)

r=section('runs'); rt=tables(r); runtime=re.search(r'<details>.*?</details>',r,re.S).group(0)
runs='<h2>4. 공개 모델을 활용해 “한 장씩 넣고 결과를 모으는 실험 도구”를 만들었다</h2>'+p('이번에 새 비전 모델을 학습시킨 것은 아니다. 공개된 모델을 로컬에서 실행할 수 있도록 준비하고, 같은 샘플을 각 모델에 넣어 결과를 파일로 저장하는 프로그램을 구성하였다. 한 이미지에서 나온 설명과 글자를 나란히 비교할 수 있게 한 것이다.')
runs+='<h3>4-1. 프로그램은 한 이미지에 대해 이렇게 동작하였다</h3>'+table(['순서','실제로 한 일','얻은 결과'],[['① 이미지 열기','방향·배경·파일 형식을 정리하였다.','모델이 읽을 수 있는 입력 이미지'],['② 그림 설명시키기','Patch-ioner에 전체 이미지를 넣었다. 진단 42개에는 Florence도 실행하였다.','전체 설명 문장과 영역별 설명'],['③ 글자 읽히기','PP-OCRv5와 EasyOCR에 같은 이미지를 넣었다.','읽은 문자열, 글자 위치, 모델이 반환한 점수'],['④ 조건을 바꾸어 다시 보기','일부 샘플에 확대·배경 변경·분할을 적용하였다.','처리 전후의 OCR 결과'],['⑤ 결과 모으기','각 출력의 출처와 실행 시간을 함께 저장하였다.','이미지별 결과 파일과 비교 화면']])
runs+=p('중요한 점은, <b>이 단계에서 각 모델은 이미지 자체만 보았다는 것</b>이다. 기존 alt나 정답을 먼저 알려주면 이미지에서 얻은 정보인지 구분하기 어려우므로, 비전 모델 입력에서 제외하였다.')+'<h3>4-2. 모든 모델을 299개에 돌린 것은 아니다</h3>'+rt[0]+p('기본 비교인 Patch-ioner와 두 OCR는 각각 299개에 실행하였다. 더 자세한 설명을 뽑는 Florence와 영역별 패치 집계는 공통 42개에 추가하였다. EasyOCR 보완 실험만은 투명 이미지 등을 더 확인하여 85개를 처리하였다.')
runs+='<h3>4-3. “이미지의 일부만 모아 설명하면 나아질까?”도 확인하였다</h3>'+p('Patch-ioner의 영역 기능도 실제로 시험하였다. Florence가 이미지 안에서 설명할 영역을 찾게 한 뒤, 그 영역에 해당하는 패치 정보를 모아 Patch-ioner가 다시 설명하도록 연결하였다. 사람이 정답 영역을 지정한 실험은 아니며, 두 공개 모델을 연결한 추가 비교이다.')+ul(['공개 모델에 추가 학습은 하지 않았다.','Paddle 전체 299개 결과 중 먼저 실행한 42개는 재사용하고, 나머지 257개를 추가 실행하였다.','GTX 1660 6GB 환경에서 실행하였다. PP-OCRv5는 CPU, 나머지 모델은 GPU를 사용하였다.'])+runtime
replace('runs',runs)

f=section('findings')
f=f.replace('<h2>5. 확인해 보니 이렇게 나왔다</h2>','<h2>5. 돌려 보니, 글자를 읽는 일과 장면을 설명하는 일은 결과가 달랐다</h2>'+p('먼저 개별 이미지를 보고 모델 출력을 대조하였다. 아래에서는 대표적인 결과를 말로 설명한 뒤, 같은 경향을 확인하기 위해 정리한 수치를 붙였다. 수치가 높다고 곧바로 대회에서 좋은 점수가 나온다는 뜻은 아니다.'))
f=f.replace('<h3>5-1. 한국어 문구는 OCR에서 더 직접적으로 확보되었다</h3>','<h3>5-1. 로고와 안내문의 핵심 글자는 OCR가 더 직접적으로 읽었다</h3>'+p('국립중앙도서관 로고를 넣었을 때, Patch-ioner는 “사람이 있는 표지판”처럼 설명하였다. 반면 OCR에는 “문화체육관광부”, “국립중앙도서관”이 남았다. 이런 이미지에서는 그림의 인상을 길게 설명하는 것보다 실제 글자를 읽는 단계가 필요함을 확인하였다.')+p('이 차이를 조금 더 확인하려고 29개 이미지에서 기관명·날짜·전화번호 등 72개 문구를 골랐다. 각 모델의 출력에 그 문구가 남았는지 세어 보니 다음과 같았다. <b>57/72는 “선정한 72문구 중 57개가 출력에 있었다”는 뜻</b>이며, 전체 OCR 정확도 79.2%라는 뜻은 아니다.'))
f=f.replace('<h3>5-2. 상세한 caption에도 지어낸 정보가 있었다</h3>','<h3>5-2. Florence가 그림을 더 잘 잡은 사례도 있었지만, 그대로 믿을 수는 없었다</h3>'+p('마이크를 들고 말하는 사진에서는 Patch-ioner가 마이크를 와인잔으로 설명했고, Florence는 마이크를 알아보았다. 악수 아이콘도 Florence는 악수로 설명하였다. 그래서 그림·사진의 내용을 보완할 비교 모델로 활용할 여지는 있었다.')+p('그러나 국민연금 문구가 있는 홍보 이미지를 Florence가 “한국 드라마 홍보물”이라고 설명한 사례도 있었다. 사진의 큰 형태를 알아봐도 목적이나 상황을 지어낼 수 있었던 것이다. 핵심 36개를 이미지와 직접 대조한 기록은 아래와 같다.'))
f=f.replace('<h3>5-3. 패치 집계 범위를 바꾸어도 오류가 남았다</h3>','<h3>5-3. 부분을 골라 설명하게 해도 오류가 자동으로 해결되지는 않았다</h3>'+p('마이크 사진의 전체 설명이 틀렸으므로, 이미지 일부에 집중하도록 패치를 모아 다시 설명하게 하였다. 출력은 달라졌지만 마이크가 이번에는 전화기로 바뀌었다. 로고에서는 기관명 대신 따옴표가 반복되었다. 즉, 보는 범위를 조절하는 기능과 한글을 읽는 능력은 다른 문제였다.'))
f=f.replace('<h3>5-4. 데이터가 잘 처리되었다는 것과 설명이 맞다는 것은 달랐다</h3>','<h3>5-4. 확대와 분할도 “많이 하면 좋아지는 처리”는 아니었다</h3>'+p('16×16 숫자 3은 확대 후 두 OCR에서 읽혔다. 반면 큰 포스터는 나눠 읽은 결과를 합치는 과정에서 제목이나 날짜가 끊어졌다. PP-OCRv5의 선택 문구 포함 수도 기본 57개에서 보완 후 56개로 줄었다. 따라서 보완 처리는 효과를 확인하면서 적용하고, 원래 결과도 함께 보관해야 한다고 판단하였다.')+'<h3>5-5. 여기까지 확인한 범위</h3>')
replace('findings',f)

e=section('examples'); e=e.replace('<h2>6. 실제 이미지를 놓고 비교한 대표 사례 12개</h2>','<h2>6. 실제 이미지를 보면 위 결과를 더 쉽게 이해할 수 있다</h2>'+p('예시는 “이미지에 실제로 무엇이 있는가 → 그림 설명 모델은 무엇이라고 했는가 → OCR에는 어떤 글자가 남았는가” 순서로 보면 된다. 잘된 사례와 틀린 사례를 함께 넣었다. 아래 12개 외에 유형별 43개 예시와 299개 전체 결과도 별도 페이지에서 볼 수 있다.'))
